# owner: platform
"""Tests for the weekly timesheet rows."""

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
import unittest

def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Bo", 9, 10),
            make_shift("Ana", 9, 13),
            make_shift("Bo", 11, 12)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ana: 1 shifts, 4.0 hours",
                "Bo: 2 shifts, 2.0 hours"
            ]
        )

    def test_one_decimal(self):
        shifts = [Shift("Ana", "tue", Span(540, 620))]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Ana: 1 shifts, 1.3 hours"]
        )

    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", 9, 10)])
